-- Batch 03: reviewed internal project material pages, immutable source hashes.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261124_v4';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; source_row jsonb; sub_batch int:=3; expected_before int:=49; expected_added int:=24;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261124_v4_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261124_v4_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 -- Serialize the brief data transaction against other writes, not normal reads.
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.project_material_library,public.project_material_library_pages IN SHARE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($spec$[{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"column_spacing","type":"numeric","unit":"m","pat":"标[ ]*准[ ]*柱[ ]*间[ ]*距：([0-9]+)米","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"depth","type":"numeric","unit":"m","pat":"标[ ]*准[ ]*层[ ]*进[ ]*深：([0-9]+)米","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"raised_floor_cm","type":"integer","unit":"cm","pat":"网[ ]*络[ ]*地[ ]*板[ ]*高[ ]*度：([0-9]+)厘米","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"hvac_cooling_water_24h","type":"boolean","unit":"boolean","pat":"(提供24小时空调冷却水)","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"telecom_provider","type":"text","unit":"provider_names","pat":"通[ ]*讯[ ]*服[ ]*务[ ]*商：(移动、联通、电信)","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"power_system","type":"text","unit":"configuration","pat":"双[ ]*路[ ]*供[ ]*电：(市政双路供电)","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"power_backup_generator","type":"text","unit":"configuration","pat":"后[ ]*备[ ]*电[ ]*源：(备用应急柴油发电机组)","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"parking_total","type":"integer","unit":"count","pat":"停[ ]*车[ ]*位：([0-9]+)个；地上[0-9]+个，地下[0-9]+个","note":"whole project shared parking; historical brochure"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"parking_above","type":"integer","unit":"count","pat":"停[ ]*车[ ]*位：[0-9]+个；地上([0-9]+)个，地下[0-9]+个","note":"whole project shared parking; historical brochure"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"parking_underground","type":"integer","unit":"count","pat":"停[ ]*车[ ]*位：[0-9]+个；地上[0-9]+个，地下([0-9]+)个","note":"whole project shared parking; historical brochure"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"hvac_pm25_purification","type":"boolean","unit":"boolean","pat":"(PM2[.]5空气净化系统：设置初效)","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"37ee8a6e-639c-5739-b9bc-0ff752902099","pg":31,"hash":"9613bc11b529f753d4470d184a84c36d610bf6b0c8d9f9d567d53a21b2b0b621","f":"delivery_standard","type":"text","unit":"configuration","pat":"交[ ]*付[ ]*标[ ]*准：(墙身：白色乳胶漆；天花吊顶：由租户自行安装；网络地板)","note":"historical project standard; not current available unit specification"},{"lib":"58839839-303e-5716-aff6-f0ef8dc7c30d","pg":10,"hash":"19d908674ae741860500838ec11efda3ef0a0c6e0123aafe7ab79454fbc77bbc","f":"depth","type":"numeric","unit":"m","pat":"进深[[:space:]]+([0-9]+) m","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"58839839-303e-5716-aff6-f0ef8dc7c30d","pg":10,"hash":"19d908674ae741860500838ec11efda3ef0a0c6e0123aafe7ab79454fbc77bbc","f":"column_spacing","type":"numeric","unit":"m","pat":"柱间距[[:space:]]+([0-9.]+) m","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"58839839-303e-5716-aff6-f0ef8dc7c30d","pg":10,"hash":"19d908674ae741860500838ec11efda3ef0a0c6e0123aafe7ab79454fbc77bbc","f":"building_height","type":"numeric","unit":"m","pat":"楼体高度[[:space:]]+([0-9.]+) m","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"58839839-303e-5716-aff6-f0ef8dc7c30d","pg":10,"hash":"19d908674ae741860500838ec11efda3ef0a0c6e0123aafe7ab79454fbc77bbc","f":"efficiency_rate","type":"numeric","unit":"percent","pat":"整层使用率[[:space:]]+Appx[.] ([0-9]+)%","note":"approximate whole-floor efficiency per historical brochure"},{"lib":"58839839-303e-5716-aff6-f0ef8dc7c30d","pg":11,"hash":"f3e7cf6ffb98bda7e3e2927697bcea16cc585282293624fe7f5161a4d82710ba","f":"power_system","type":"text","unit":"configuration","pat":"备用电力[[:space:]]+(真双路供电、柴油发电机、UPS系统)","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"58839839-303e-5716-aff6-f0ef8dc7c30d","pg":11,"hash":"f3e7cf6ffb98bda7e3e2927697bcea16cc585282293624fe7f5161a4d82710ba","f":"power_backup_generator","type":"text","unit":"configuration","pat":"备用电力[[:space:]]+真双路供电、(柴油发电机)、UPS系统","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"58839839-303e-5716-aff6-f0ef8dc7c30d","pg":11,"hash":"f3e7cf6ffb98bda7e3e2927697bcea16cc585282293624fe7f5161a4d82710ba","f":"elevator_zones","type":"text","unit":"configuration","pat":"客用电梯数量[[:space:]]+(高区写字楼客梯5部、低区商业客梯2部、观光梯2部)","note":"separate office retail and sightseeing elevators, no summing"},{"lib":"56d040aa-8fb1-5044-b41e-baec00e52a1a","pg":12,"hash":"e9cc5d47f00312acfb2650f163082e3a3e413134c702e4fbad0396ee6cca2953","f":"parking_underground","type":"integer","unit":"count","pat":"车库[[:space:]]+B2-B4，约([0-9]+)个","note":"approximate parking spaces B2-B4; not total parking"},{"lib":"56d040aa-8fb1-5044-b41e-baec00e52a1a","pg":12,"hash":"e9cc5d47f00312acfb2650f163082e3a3e413134c702e4fbad0396ee6cca2953","f":"efficiency_rate","type":"numeric","unit":"percent","pat":"使用率([0-9]+)%","note":"office efficiency per archived brochure"},{"lib":"56d040aa-8fb1-5044-b41e-baec00e52a1a","pg":12,"hash":"e9cc5d47f00312acfb2650f163082e3a3e413134c702e4fbad0396ee6cca2953","f":"hvac_pm25_purification","type":"boolean","unit":"boolean","pat":"(PM2[.]5空气净化系统)","note":"reviewed historical brochure; project-level parameter, not independent current survey"},{"lib":"218201e0-34cd-50ad-af82-a0edb608dace","pg":10,"hash":"cc1482b087230be32b215c3c51bd95abb7969e8fe66186d7476e4074be9c0aab","f":"floor_height","type":"numeric","unit":"m","pat":"层高 ([0-9.]+)m","note":"standard floor height, not clear height"},{"lib":"d2a705c7-1a4a-5794-8e8c-a5094049a56d","pg":25,"hash":"c96dbf113f4f340a85d5ddff1533c2863df0b97deb02c0bd28af3edd81a24db6","f":"power_system","type":"text","unit":"configuration","pat":"供电系统[[:space:]]+(双路供电)","note":"reviewed same-project technical page; historical configuration, not general area data"}]$spec$::jsonb) v(lib uuid,pg int,f text,type text,unit text,pat text,hash text,note text)), scope AS (
SELECT l.id lib,(array_agg(distinct bid::uuid))[1] bid FROM public.project_material_library l CROSS JOIN LATERAL jsonb_array_elements(l.payload->'sections') s CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(s->'candidate_building_ids')='array' THEN s->'candidate_building_ids' ELSE '[]'::jsonb END) bid WHERE l.review_state='reviewed' AND s->>'association_status'='confirmed' GROUP BY l.id HAVING count(distinct bid)=1
), c AS (
SELECT b.id bid,b.name,d.id target_id,v.f field_name,
 CASE v.type WHEN 'numeric' THEN to_jsonb(m.val::numeric) WHEN 'integer' THEN to_jsonb(m.val::integer) WHEN 'boolean' THEN to_jsonb(true) ELSE to_jsonb(trim(regexp_replace(m.val,'[[:space:]]+',' ','g'))) END new_value,
 v.type value_type,'project_material_library' source_table,l.id source_id,'page:'||v.pg source_field,'internal_archived_page' source_kind,v.unit,
 v.note||'; page_sha256='||v.hash||'; original native text preserved inside database' note
FROM specs v JOIN scope s ON s.lib=v.lib JOIN public.project_material_library l ON l.id=s.lib
JOIN public.project_material_library_pages p ON p.extraction_id=l.id AND p.page_number=v.pg AND p.content_sha256=v.hash
JOIN public.buildings b ON b.id=s.bid JOIN public.building_brochure_data d ON d.building_id=b.id
CROSS JOIN LATERAL (SELECT (regexp_match(p.content->>'native_text',v.pat))[1] val) m
WHERE b.is_active AND b.city IN ('北京','北京市') AND b.project_type='stock' AND b.tracking_scope='tracked' AND b.merged_into_id IS NULL AND (SELECT count(*) FROM public.building_brochure_data d2 WHERE d2.building_id=b.id)=1
AND to_jsonb(d)->v.f='null'::jsonb AND m.val IS NOT NULL
) SELECT c.* FROM c
WHERE NOT EXISTS (SELECT 1 FROM public.building_data_field_provenance p WHERE p.building_id=c.bid AND p.target_table='building_brochure_data' AND p.field_name=c.field_name)
AND NOT EXISTS (SELECT 1 FROM public.audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=c.target_id::text AND (a.details->>'field_name'=c.field_name OR a.new_values ? c.field_name))
ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  VALUES(r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,'brochure','secondary','高力国际已审阅历史项目资料',now_ts,now_ts,'legacy_backfill',ev,'batch_ref=ai_building_field_backfill_20261124_v4_100; source_table='||r.source_table||'; source_record_id='||r.source_id||'; source_field='||r.source_field||'; unit='||r.unit||'; '||r.note||'; AI-assisted',true);
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261124_v4_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_table',r.source_table,'source_record_id',r.source_id,'source_field',r.source_field,'source_kind',r.source_kind,'unit',r.unit,'verification_status','legacy_backfill','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR NOT EXISTS(SELECT 1 FROM public.building_data_field_provenance p JOIN public.audit_logs a ON a.event_id='ai_field_fill:'||ev::text WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value AND a.new_values->r.field_name=p.field_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected % qualifying fields, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261124_v4_100';
COMMIT;